 for(const auto& c:helpers) {
  const auto source=source_for(c.source_variant);const auto before=serialize_embedding_workbench_raw_log_json(source);
  std::vector<LogActivityVariantGroup> groups;
  for(const auto& [key,selected]:c.groups) {
    LogActivityVariantGroup group;group.variant=key;
    for(auto i:selected)group.traces.push_back(source.traces.at(i));groups.push_back(group);
  }
  const auto counts_before=c.counts;const auto ranked_before=c.ranked;bool returned=false;
  EventLog all_before;for(const auto& group:groups)all_before.traces.insert(all_before.traces.end(),group.traces.begin(),group.traces.end());
  const auto groups_before=serialize_embedding_workbench_raw_log_json(all_before);
  try {
   const auto result=filter_log_by_start_activities(c.counts,groups,c.ranked,c.threshold,c.key);
   returned=true;assert(c.error_kind==0);
   assert(serialize_embedding_workbench_raw_log_json(result)==serialize_embedding_workbench_raw_log_json(expected_for(source,c.selected,true)));
  }catch(const std::out_of_range& e){assert(c.error_kind!=0);if(c.error_kind==2)assert(std::string(e.what())=="list index out of range");else assert(std::string(e.what()).find(c.key)!=std::string::npos);}
  assert(returned==(c.error_kind==0));assert(c.counts==counts_before && c.ranked==ranked_before);
  EventLog all_after;for(const auto& group:groups)all_after.traces.insert(all_after.traces.end(),group.traces.begin(),group.traces.end());
  assert(serialize_embedding_workbench_raw_log_json(all_after)==groups_before);
  assert(serialize_embedding_workbench_raw_log_json(source)==before);
 }
